from itertools import product

colors = [0, 1]
for coloring in product(colors, repeat=21):
    # Convert coloring to list of integers
    coloring = list(coloring)

    # Check if the partial assignment is respected
    if coloring[3] != 0 or coloring[7] != 0 or coloring[12] != 0 or coloring[18] != 0:
        continue

    # Check for monochromatic red cliques of size 4
    for i in range(7):
        for j in range(i+1, 7):
            for k in range(j+1, 7):
                for l in range(k+1, 7):
                    # Calculate the indices of the edges in the coloring list
                    ij = i*6 + j - (i+1)
                    ik = i*6 + k - (i+1)
                    il = i*6 + l - (i+1)
                    jk = j*6 + k - (j+1)
                    jl = j*6 + l - (j+1)
                    kl = k*6 + l - (k+1)

                    # Check if all edges are red
                    if coloring[ij] == coloring[ik] == coloring[il] == coloring[jk] == coloring[jl] == coloring[kl] == 0:
                        break
                else:
                    continue
                break
            else:
                continue
            break
        else:
            continue
        break
    else:
        # Check for monochromatic blue cliques of size 3
        for i in range(7):
            for j in range(i+1, 7):
                for k in range(j+1, 7):
                    # Calculate the indices of the edges in the coloring list
                    ij = i*6 + j - (i+1)
                    ik = i*6 + k - (i+1)
                    jk = j*6 + k - (j+1)

                    # Check if all edges are blue
                    if coloring[ij] == coloring[ik] == coloring[jk] == 1:
                        break
                else:
                    continue
                break
            else:
                continue
            break
        else:
            print(coloring)
            break
else:
    print("UNSATISFIABLE")
